#!/usr/bin/env python3
"""Turns the JSON written by gen-fixtures.cjs into Tests/NearSignerCoreTests/Fixtures.swift and
host/python/test_fixtures.json. Usage: fixtures-to-swift.py fixtures.json"""

import json
import os
import sys

root = os.path.abspath(os.path.join(os.path.dirname(__file__), ".."))
d = json.load(open(sys.argv[1]))
s = json.dumps
lines = [
    "// Generated by scripts/regenerate-fixtures.sh with near-api-js 7.3.1, near-seed-phrase 0.2.1 and tweetnacl 1.0.3.",
    "// These come from independent implementations and pin the Swift code to the canonical encodings.",
    "// Do not edit by hand.",
    "",
    "enum Fixtures {",
]
for key in ["phrase", "ledgerPath", "cliPath", "ledgerPublicKey", "ledgerSecretKey", "cliPublicKey", "cliSecretKey"]:
    lines.append(f"    static let {key} = {s(d[key])}")
lines += [
    "",
    "    struct TransactionFixture { let name: String; let borsh: String; let hash: String; let signature: String; let signed: String }",
    "    static let transactions: [TransactionFixture] = [",
]
for name, t in d["transactions"].items():
    lines.append(f"        TransactionFixture(name: {s(name)}, borsh: {s(t['borsh'])}, hash: {s(t['hash'])},")
    lines.append(f"                           signature: {s(t['signature'])}, signed: {s(t['signed'])}),")
lines += [
    "    ]",
    "",
    "    /// `encodeDelegateAction` output: NEP-366 prefix followed by borsh(DelegateAction).",
    f"    static let delegatePrefixedBorsh = {s(d['delegate']['prefixedBorsh'])}",
    f"    static let delegateHash = {s(d['delegate']['hash'])}",
    f"    static let delegateSignature = {s(d['delegate']['signature'])}",
    f"    static let relayTransactionBorsh = {s(d['relayTransaction']['borsh'])}",
    f"    static let nep413Payload = {s(d['nep413']['payload'])}",
    f"    static let nep413Hash = {s(d['nep413']['hash'])}",
    f"    static let nep413Signature = {s(d['nep413']['signature'])}",
    "}",
]
with open(os.path.join(root, "Tests/NearSignerCoreTests/Fixtures.swift"), "w") as out:
    out.write("\n".join(lines) + "\n")

t = d["transactions"]
python = {
    "publicKey": d["ledgerPublicKey"],
    "transfer": t["transfer"],
    "functionCall": t["functionCall"],
    "deployContract": t["deployContract"],
    "delegatePrefixed": d["delegate"]["prefixedBorsh"],
}
with open(os.path.join(root, "host/python/test_fixtures.json"), "w") as out:
    out.write(json.dumps(python, indent=2) + "\n")
